UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>AUR30320 Certificate III in Automotive Electrical Technology</strong></h1> <p>This qualification reflects the role of individuals who service, diagnose and repair electrical systems and components in vehicles in the automotive electrical service and repair industry.</p> </div>',
    total_course_duration = '104 Weeks (Includes term breaks)',
    offshore_tuition_fee = 30000,
    enrolment_fee = 200,
    materials_fee = 2000,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645787573297-1de0d9ea-2159" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) follow the AUR Training package guidance for the entry requirements for this qualification. There are no entry requirements for this qualification and direct entry is accepted.</p> <h4>Academic Requirements:</h4> <ul> <li>Minimum completion of Australian Year 12 secondary school education equivalent or above.</li> </ul> <h4>English Language Requirements:</h4> <ul> <li> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </li> </ul> <h4>Physical requirements</h4> <ul> <li>Participants will be made aware that this course requires physical tasks including manual handling such as inventory and using heavy equipment’s in a mechanical workshop setting.</li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/aur30320-certificate-iii-in-automotive-electrical-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '116640D';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>AUR30620 Certificate III in Light Vehicle Mechanical Technology</strong></h1> <p>This qualification reflects the role of individuals who perform a broad range of tasks on a variety of light vehicles in the automotive retail, service and repair industry.</p> </div>',
    total_course_duration = '78 Weeks(Includes term breaks)',
    offshore_tuition_fee = 22800,
    enrolment_fee = 200,
    materials_fee = 1500,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645787573297-1de0d9ea-2159" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) follow the AUR Training package guidance for the entry requirements for this qualification. There are no entry requirements for this qualification and direct entry is accepted.</p> <h4>Academic Requirements:</h4> <ul> <li>Minimum completion of Australian Year 12 secondary school education equivalent or above.</li> </ul> <h4>English Language Requirements:</h4> <ul> <li>Academic IELTS 6 overall, no less than 5.5 in each band, or upper intermediate, or EAP from approved ELICOS/ESL centre.</li> <li>Any AQF qualification at the Certificate III level or above in any discipline area delivered and assessed in English only will be deemed as meeting both the academic and English language entry requirements.</li> <li> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </li> </ul> <h4>Physical requirements:</h4> <p>Participants will be made aware that this course requires physical tasks including manual handling such as inventory and using heavy equipment’s in a mechanical workshop setting.</p> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/aur30620-certificate-iii-in-light-vehicle-mechanical-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '104584F';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>AUR32721 Certificate III in Automotive Electric Vehicle Technology</strong></h1> <p>This qualification reflects the role of individuals who service, diagnose and repair battery electric vehicles and components in the automotive, service and repair industry who carry out work according to Australian Standards (AS) 5732 Electric vehicle operations – Maintenance and repair.</p> <h3>Study And Enjoy Multicultural Burwood</h3> <p>Skyline International College, Burwood campus is just 12 minutes by train from the heart of the city of Sydney. The campus is in the center of Burwood and is just 2 minutes of walk from the Burwood train station or bus stop. Burwood is multicultural and is a destination for international students to live and work.</p> </div>',
    total_course_duration = '104 Weeks(Includes term breaks)',
    offshore_tuition_fee = 28000,
    enrolment_fee = 200,
    materials_fee = 2000,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645787573297-1de0d9ea-2159" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) follow the AUR Training package guidance for the entry requirements for this qualification. There are no entry requirements for this qualification and direct entry is accepted.</p> <h4>Academic Requirements:</h4> <ul> <li>Minimum completion of Australian Year 12 secondary school education equivalent or above.</li> </ul> <h4>English Language Requirements:</h4> <ul> <li> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </li> </ul> <h4>Physical requirements</h4> <ul> <li>Participants will be made aware that this course requires physical tasks including manual handling such as inventory and using heavy equipment’s in a mechanical workshop setting.</li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/aur32721-certificate-iii-in-automotive-electric-vehicle-technology/',
    updated_at = NOW()
WHERE cricos_course_code = '116639H';
