UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>AUR50126 Diploma of Automotive Management</strong></h1> <p>This qualification reflects the role of individuals who undertake leadership and management roles in the automotive industry. It is suitable for entry into senior management roles in all sectors of the automotive industry.</p> </div>',
    total_course_duration = '52 Weeks(Includes term breaks)',
    offshore_tuition_fee = 13200,
    enrolment_fee = 200,
    materials_fee = 400,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645787573297-1de0d9ea-2159" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>International students must be 18 years or older and provide evidence to demonstrate both academic and English language entry requirements as follows:</p> <h4>Academic Requirements:</h4> <ul> <li>Successful completion of Year 12 or equivalent; or other relevant qualification/s</li> </ul> <h4>English Language Requirements:</h4> <ul> <li> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/aur50116-diploma-of-automotive-management/',
    updated_at = NOW()
WHERE cricos_course_code = '120390E';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>BSB50420 Diploma of Leadership and Management</strong></h1> <p>The Diploma of Leadership and Management has been designed for individuals who apply knowledge, practical skills and experience in leadership and management across a range of enterprise and industry contexts.</p> <p>Individuals at this level display initiative and judgement in planning, organising, implementing and monitoring their own workload and the workload of others. They use communication skills to support individuals and teams to meet organisational or enterprise requirements.</p> <p>They may plan, design, apply and evaluate solutions to unpredictable problems, and identify, analyse and synthesise information from a variety of sources</p> <h3>OUR CAMPUS IS IN MULTICULTURAL BURWOOD</h3> <p>Skyline International College is just 12 minutes by train from the heart of the city of Sydney. The head office and main campus is in the center of Burwood and is just 2 minutes from the Burwood train station or bus stop. Burwood is multicultural and a destination for international<br/> students to study, live and work.</p> </div>',
    total_course_duration = '52 Weeks(includes term breaks)',
    offshore_tuition_fee = 10000,
    enrolment_fee = 200,
    materials_fee = 200,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645848807218-2549d782-e36f" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>International students must be 17 years or older and provide evidence to demonstrate both academic and English language entry requirements as follows:</p> <h4>Academic Requirements:</h4> <ul> <li>Successful completion of Year 12 or equivalent; or other relevant qualification/s</li> </ul> <h4>English Language Requirements:</h4> <ul> <li> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/bsb50420-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '104344M';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>BSB60420 Advanced Diploma of Leadership and Management</strong></h1> <p>The Advanced Diploma of Leadership and Management has been designed for individuals who apply specialised knowledge and skills, together with experience in leadership and management, across a range of enterprise and industry contexts.</p> <p>Individuals at this level use initiative and judgement to plan and implement a range of leadership and management functions, with accountability for personal and team outcomes within broad parameters.</p> <p>They use cognitive and communication skills to identify, analyse and synthesise information from a variety of sources and transfer their knowledge to others, and creative or conceptual skills to express ideas and perspectives or respond to complex problems.</p> <h3>OUR CAMPUS IS IN MULTICULTURAL BURWOOD</h3> <p>Skyline International College is just 12 minutes by train from the heart of the city of Sydney. The head office and main campus is in the center of Burwood and is just 2 minutes from the Burwood train station or bus stop. Burwood is multicultural and is a destination for international<br/> students to study, live and work.</p> </div>',
    total_course_duration = '65 Weeks(Includes term breaks)',
    offshore_tuition_fee = 12500,
    enrolment_fee = 200,
    materials_fee = 250,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645849665771-f89409fc-6dca" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>International students must be 18 years or older and provide evidence to demonstrate both academic and English language entry requirements as follows:</p> <h4>Academic Requirements:</h4> <ul> <li>Successful completion of Year 12 or equivalent; or other relevant school qualification/s and</li> <li>A Diploma or Advanced Diploma course from the Business Services Training Package. (current or superseded equivalent versions)</li> </ul> <h4>English Language Requirements:</h4> <ul> <li>Academic IELTS 6 overall, no less than 5.5 in each band, or upper intermediate, or EAP from approved ELICOS/ESL centre</li> </ul> <p>The academic entry requirement of the Diploma of Advanced Diploma qualification from the Business Services Training Package delivered and assessed in English only will be deemed as meeting the English language entry requirements.</p> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/bsb60420-advanced-diploma-of-leadership-and-management/',
    updated_at = NOW()
WHERE cricos_course_code = '106373A';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>BSB80120 Graduate Diploma Of Management (Learning)</strong></h1> <p>This qualification reflects the roles of individuals who apply highly specialised knowledge and skills in the field of organisational learning and capability development. Individuals in these roles generate and evaluate complex ideas. They also initiate, design and execute major learning and development functions within an organisation. Typically, they would have full responsibility and accountability for the personal output and work of others.</p> <div class="wpb_text_column"> <div class="wpb_wrapper"> <p>This qualification may apply to leaders and managers in an organisation where learning is used to build organisational capability.</p> </div> </div> </div>',
    total_course_duration = '78 Weeks(Includes term breaks)',
    offshore_tuition_fee = 22800,
    enrolment_fee = 200,
    materials_fee = 600,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645851265855-a2173c30-a17c" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>International students must be 18 years or older and provide evidence to demonstrate both academic and English language entry requirements as follows:</p> <h4>Academic Requirements:</h4> <ul> <li> Successful completion of Year 12 or equivalent or other relevant school qualification/s<br/> and</li> <li>A student interview may be conducted prior to enrolment to verify suitability for BSB80120 Graduate Diploma of Management (Learning).</li> </ul> <h4>English Language Requirements:</h4> <ul> <li> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/bsb80120-graduate-diploma-of-management-learning/',
    updated_at = NOW()
WHERE cricos_course_code = '106374M';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1 style="font-size: 2.5rem;"><strong>Certificate III in Early Childhood Education &amp; Care With Skyline International College</strong></h1> <p>Choosing a career in early childhood education means choosing purpose, stability, and the chance to shape young lives positively every day. Skyline International College delivers industry-aligned training designed to prepare students for fundamental roles in regulated care settings, starting with the certificate 3 in early childhood and care. This qualification is ideal for those who want practical skills, recognised credentials, and meaningful employment opportunities across Australia.</p> <p>Early childhood educators play a critical role in helping children feel safe, confident, and supported during their most formative years. This course equips students with the knowledge and hands-on experience required to meet national standards while working confidently within approved learning frameworks.</p> <section class="mbr-section courses-section"> <div class="lw_col-inner"> <h2 style="font-size: 2.5rem;"><strong>CHC30125 Certificate III in Early Childhood Education and Care</strong></h2> <p>This qualification reflects the role of educators in early childhood education and care who work in regulated children’s education and care services in Australia. They support children’s wellbeing, and development in the context of an approved learning framework. Educators use a range of well-developed skills and knowledge, using discretion and judgment when carrying out their work in the context of established policies and procedures. They may work independently or under the guidance of others, though in some contexts that guidance may not be on-site.</p> <p>Early childhood educators work in long day care centres, family day care, pre-schools or kindergartens.</p> <p>To achieve this qualification, the individual must have completed a total of least 160 hours of work in a regulated children’s education and care service in Australia as detailed in the Assessment Requirements of units of competency. The total number of hours may be applied collectively across all units of competency that include the requirement for workplace hours.</p> <p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p> <p>Under the Education and Care Services National Law (2011) the Australian Children’s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here: <a data-wpel-link="external" href="http://www.acecqa.gov.au" rel="nofollow noopener external noreferrer" target="_blank">www.acecqa.gov.au</a>.</p> <h2 style="font-size: 2.5rem;"><strong>What You’ll Gain From This Qualification</strong></h2> <p>This course focuses on developing capable, job-ready educators who understand both the emotional and practical aspects of working with children.</p> <p>Key learning outcomes include:</p> <ul class="catpara"> <li><strong>Child development fundamentals –</strong> Understand how children grow socially, emotionally, and physically</li> <li><strong>Safe care practices –</strong> Maintain health, safety, and well-being in care environments</li> <li><strong>Learning through play –</strong> Support age-appropriate learning experiences</li> <li><strong>Professional communication skills –</strong> Build trust with families and colleagues</li> <li><strong>Regulatory awareness –</strong> Work confidently within policies and procedures</li> </ul> <p>Each skill is designed to reflect real workplace expectations, ensuring students graduate with confidence and competence.</p> <p><img alt="Course Image" class="title-img" decoding="async" src="https://sic.edu.au/wp-content/uploads/2024/10/childhood-care1.jpg"/></p> <h2 style="font-size: 2.5rem;"><strong>Career Opportunities After Completion</strong></h2> <p>The early childhood sector continues to grow, creating consistent demand for trained educators. Completing the certificate 3 in childcare opens pathways into a range of roles across regulated education and care services.</p> <p>Possible career outcomes include:</p> <ul class="catpara"> <li><strong>Early Childhood Educator –</strong> Support daily learning and routines</li> <li><strong>Childcare Assistant –</strong> Assist qualified educators in centre-based care</li> <li><strong>Family Day Care Educator –</strong> Provide care in approved home settings</li> <li><strong>Preschool or Kindergarten Support Staff –</strong> Help deliver early learning programs</li> </ul> <p>These roles offer stability, flexibility, and opportunities for long-term career growth.</p> <h2 style="font-size: 2.5rem;"><strong>Hands-On Training That Builds Real Confidence</strong></h2> <p>Practical experience is a core part of this qualification. Students complete structured workplace training in approved education and care services, allowing them to apply classroom learning in real-world environments.</p> <p>Workplace learning benefits include:</p> <ul class="catpara"> <li>Real exposure to day-to-day childcare operations</li> <li>Development of professional judgement and independence</li> <li>Increased employability upon course completion</li> <li>Confidence working with children of different age groups</li> </ul> <p>This balance of theory and practice ensures graduates are workplace-ready from day one.</p> <h2 style="font-size: 2.5rem;"><strong>A Smart Starting Point for Future Growth</strong></h2> <p>The certificate 3 in early childhood and care is not only a qualification—it’s a foundation. Many graduates choose to continue their studies with higher-level early childhood qualifications, expanding their career prospects and leadership potential within the sector.</p> <h2 style="font-size: 2.5rem;"><strong>Enrol Now Towards a Meaningful Career</strong></h2> <p>Build a career where your work truly matters. <a data-wpel-link="internal" href="https://sic.edu.au/admissions-skyline-international-college/">Get enrolled in Skyline International College</a> to learn more about enrolment options, course delivery, and upcoming intakes. You can enroll many more courses from us, such as <a data-wpel-link="internal" href="https://sic.edu.au/course/chc33021-certificate-iii-in-individual-support-ageing/">individual support</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/chc52021-diploma-of-community-services/">community services</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/cpc30220-certificate-iii-in-carpentry/">carpentry</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/cpc50220-diploma-of-building-and-construction-building/">construction management</a>, and <a data-wpel-link="internal" href="https://sic.edu.au/courses/hospitality-courses/">hospitality courses</a>.</p> </div> </section> </div>',
    total_course_duration = '52 Weeks(Includes term breaks)',
    offshore_tuition_fee = 14000,
    enrolment_fee = 200,
    materials_fee = 2000,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645787573297-1de0d9ea-2159" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) follows the Community Services Training Package guidance for the entry requirements for this qualification. There are no entry requirements for this qualification and direct entry is accepted.</p> <h4>Academic Requirements:</h4> <ul> <li>Minimum completion of Australian Year 12 secondary school education equivalent or above.</li> </ul> <h4>English Language Requirements:</h4> <ul> <li>Academic IELTS 6.0 overall, no less than 5.5 in each band, or upper intermediate, or EAP from approved ELICOS/ESL centre.</li> </ul> <p>Any AQF qualification at the Certificate III level or above in any discipline area delivered and assessed in English only will be deemed as meeting both the academic and English language entry requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> <h4>Physical requirements:</h4> <ul> <li>Participants of this course should have a certain level of fitness as it involves tasks like lifting children, cleaning, mopping, and rearranging furniture. Participants should be prepared for these manual handling responsibilities that are integral to the job.</li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/chc30121-certificate-iii-in-early-childhood-education-and-care/',
    updated_at = NOW()
WHERE cricos_course_code = '119633A';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1 style="font-size: 2.5rem;"><strong>Certificate III in Early Childhood Education &amp; Care With Skyline International College</strong></h1> <p>Choosing a career in early childhood education means choosing purpose, stability, and the chance to shape young lives positively every day. Skyline International College delivers industry-aligned training designed to prepare students for fundamental roles in regulated care settings, starting with the certificate 3 in early childhood and care. This qualification is ideal for those who want practical skills, recognised credentials, and meaningful employment opportunities across Australia.</p> <p>Early childhood educators play a critical role in helping children feel safe, confident, and supported during their most formative years. This course equips students with the knowledge and hands-on experience required to meet national standards while working confidently within approved learning frameworks.</p> <section class="mbr-section courses-section"> <div class="lw_col-inner"> <h2 style="font-size: 2.5rem;"><strong>CHC30125 Certificate III in Early Childhood Education and Care</strong></h2> <p>This qualification reflects the role of educators in early childhood education and care who work in regulated children’s education and care services in Australia. They support children’s wellbeing, and development in the context of an approved learning framework. Educators use a range of well-developed skills and knowledge, using discretion and judgment when carrying out their work in the context of established policies and procedures. They may work independently or under the guidance of others, though in some contexts that guidance may not be on-site.</p> <p>Early childhood educators work in long day care centres, family day care, pre-schools or kindergartens.</p> <p>To achieve this qualification, the individual must have completed a total of least 160 hours of work in a regulated children’s education and care service in Australia as detailed in the Assessment Requirements of units of competency. The total number of hours may be applied collectively across all units of competency that include the requirement for workplace hours.</p> <p>No occupational licensing, certification or specific legislative requirements apply to this qualification at the time of publication.</p> <p>Under the Education and Care Services National Law (2011) the Australian Children’s Education and Care Quality Authority (ACECQA) publishes lists of approved early childhood education and care qualifications and information regarding regulatory requirements here: <a data-wpel-link="external" href="http://www.acecqa.gov.au" rel="nofollow noopener external noreferrer" target="_blank">www.acecqa.gov.au</a>.</p> <h2 style="font-size: 2.5rem;"><strong>What You’ll Gain From This Qualification</strong></h2> <p>This course focuses on developing capable, job-ready educators who understand both the emotional and practical aspects of working with children.</p> <p>Key learning outcomes include:</p> <ul class="catpara"> <li><strong>Child development fundamentals –</strong> Understand how children grow socially, emotionally, and physically</li> <li><strong>Safe care practices –</strong> Maintain health, safety, and well-being in care environments</li> <li><strong>Learning through play –</strong> Support age-appropriate learning experiences</li> <li><strong>Professional communication skills –</strong> Build trust with families and colleagues</li> <li><strong>Regulatory awareness –</strong> Work confidently within policies and procedures</li> </ul> <p>Each skill is designed to reflect real workplace expectations, ensuring students graduate with confidence and competence.</p> <p><img alt="Course Image" class="title-img" decoding="async" src="https://sic.edu.au/wp-content/uploads/2024/10/childhood-care1.jpg"/></p> <h2 style="font-size: 2.5rem;"><strong>Career Opportunities After Completion</strong></h2> <p>The early childhood sector continues to grow, creating consistent demand for trained educators. Completing the certificate 3 in childcare opens pathways into a range of roles across regulated education and care services.</p> <p>Possible career outcomes include:</p> <ul class="catpara"> <li><strong>Early Childhood Educator –</strong> Support daily learning and routines</li> <li><strong>Childcare Assistant –</strong> Assist qualified educators in centre-based care</li> <li><strong>Family Day Care Educator –</strong> Provide care in approved home settings</li> <li><strong>Preschool or Kindergarten Support Staff –</strong> Help deliver early learning programs</li> </ul> <p>These roles offer stability, flexibility, and opportunities for long-term career growth.</p> <h2 style="font-size: 2.5rem;"><strong>Hands-On Training That Builds Real Confidence</strong></h2> <p>Practical experience is a core part of this qualification. Students complete structured workplace training in approved education and care services, allowing them to apply classroom learning in real-world environments.</p> <p>Workplace learning benefits include:</p> <ul class="catpara"> <li>Real exposure to day-to-day childcare operations</li> <li>Development of professional judgement and independence</li> <li>Increased employability upon course completion</li> <li>Confidence working with children of different age groups</li> </ul> <p>This balance of theory and practice ensures graduates are workplace-ready from day one.</p> <h2 style="font-size: 2.5rem;"><strong>A Smart Starting Point for Future Growth</strong></h2> <p>The certificate 3 in early childhood and care is not only a qualification—it’s a foundation. Many graduates choose to continue their studies with higher-level early childhood qualifications, expanding their career prospects and leadership potential within the sector.</p> <h2 style="font-size: 2.5rem;"><strong>Enrol Now Towards a Meaningful Career</strong></h2> <p>Build a career where your work truly matters. <a data-wpel-link="internal" href="https://sic.edu.au/admissions-skyline-international-college/">Get enrolled in Skyline International College</a> to learn more about enrolment options, course delivery, and upcoming intakes. You can enroll many more courses from us, such as <a data-wpel-link="internal" href="https://sic.edu.au/course/chc33021-certificate-iii-in-individual-support-ageing/">individual support</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/chc52021-diploma-of-community-services/">community services</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/cpc30220-certificate-iii-in-carpentry/">carpentry</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/cpc50220-diploma-of-building-and-construction-building/">construction management</a>, and <a data-wpel-link="internal" href="https://sic.edu.au/courses/hospitality-courses/">hospitality courses</a>.</p> </div> </section> </div>',
    total_course_duration = '52 Weeks(Includes term breaks)',
    offshore_tuition_fee = 14000,
    enrolment_fee = 200,
    materials_fee = 2000,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645787573297-1de0d9ea-2159" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) follows the Community Services Training Package guidance for the entry requirements for this qualification. There are no entry requirements for this qualification and direct entry is accepted.</p> <h4>Academic Requirements:</h4> <ul> <li>Minimum completion of Australian Year 12 secondary school education equivalent or above.</li> </ul> <h4>English Language Requirements:</h4> <ul> <li>Academic IELTS 6.0 overall, no less than 5.5 in each band, or upper intermediate, or EAP from approved ELICOS/ESL centre.</li> </ul> <p>Any AQF qualification at the Certificate III level or above in any discipline area delivered and assessed in English only will be deemed as meeting both the academic and English language entry requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> <h4>Physical requirements:</h4> <ul> <li>Participants of this course should have a certain level of fitness as it involves tasks like lifting children, cleaning, mopping, and rearranging furniture. Participants should be prepared for these manual handling responsibilities that are integral to the job.</li> </ul> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/chc30125-certificate-iii-in-early-childhood-education-and-care/',
    updated_at = NOW()
WHERE cricos_course_code = '119633A';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1 style="font-size: 2.5rem;"><strong>Gain Real Skills With the Certificate III in Individual Support (Ageing)</strong></h1> <p>Looking to build a career in aged care that’s both rewarding and secure? The Certificate III in Individual Support (Ageing) at <a data-wpel-link="internal" href="https://sic.edu.au/">Skyline International College</a> is a nationally recognised course designed to prepare you for fundamental roles in residential, home, or community-based aged care settings.</p> <p>Whether you’re just starting your journey or switching careers, this program is ideal for people who want to make a genuine impact in the lives of older Australians. As one of Sydney’s trusted vocational education providers, Skyline delivers hands-on, job-focused training that’s backed by industry knowledge and caring support.</p> <section class="mbr-section courses-section"> <div class="lw_col-inner"> <h2 style="font-size: 2.5rem;"><strong>CHC33021 Certificate III in Individual Support (Ageing)</strong></h2> <p>This qualification reflects the role of individuals in the community, home or residential care setting who work under supervision and delegation as a part of a multi-disciplinary team, following an individualised plan to provide person-centred support to people who may require support due to ageing, disability or some other reason.</p> <p>These individuals take responsibility for their own outputs within the scope of their job role and delegation. Workers have a range of factual, technical and procedural knowledge, as well as some theoretical knowledge of the concepts and practices required to provide person-centred support.</p> <p>The skills in this qualification must be applied in accordance with Commonwealth and State/Territory legislation, Australian standards and industry codes of practice. To achieve this qualification, the candidate must have completed at least 120 hours of work as detailed in the Assessment Requirements of the units of competency.<br/> No licensing, legislative, regulatory or certification requirements apply to this qualification at the time of publication.</p> <h2 style="font-size: 2.5rem;"><strong>Who This Course Is For</strong></h2> <p>The individual support course is tailored for:</p> <ul class="catpara"> <li>Individuals who want to work as aged care or home care assistants</li> <li>People re-entering the workforce are looking for a reliable, growing industry</li> <li>International students seeking a CRICOS-registered qualification</li> <li>Anyone who values person-centred care and wants a career that makes a difference</li> </ul> <h2 style="font-size: 2.5rem;"><strong>What You’ll Learn</strong></h2> <p>You’ll develop core skills and knowledge needed to support elderly clients with respect, safety, and dignity. Topics include:</p> <ul class="catpara"> <li>Personal care and hygiene support</li> <li>Healthy body systems and ageing processes</li> <li>Support for people with dementia or palliative needs</li> <li>Legal and ethical considerations in community care</li> <li>Working safely and effectively in a team environment</li> </ul> <p>This program combines classroom-based learning with structured work placements, giving you a chance to apply what you learn in a real care environment. Graduates leave with confidence, capability, and workplace-ready experience.</p> <h2 style="font-size: 2.5rem;"><strong>Why Go With Skyline International College?</strong></h2> <p>Skyline International College is more than just a place to study. We’re an education partner who takes your goals seriously.</p> <ul class="catpara"> <li>Registered Training Organisation (RTO) and CRICOS approved</li> <li>Small class sizes and supportive trainers with real industry experience</li> <li>Located near Sydney with easy access to public transport</li> <li>Flexible learning schedules for busy students</li> <li>Strong connections with local care providers for placement opportunities</li> </ul> <p>This isn’t just theory. You’ll graduate knowing how to perform the daily tasks expected of aged care workers, from transferring clients safely to assisting with mobility and providing compassionate support. We also offer courses like a <a data-wpel-link="internal" href="https://sic.edu.au/course/chc52021-diploma-of-community-services/">Diploma of Community Services</a>, <a data-wpel-link="internal" href="https://sic.edu.au/course/cpc30220-certificate-iii-in-carpentry/">carpentry</a> and <a data-wpel-link="internal" href="https://sic.edu.au/course/cpc50220-diploma-of-building-and-construction-building/">construction management courses</a>.</p> <h2 style="font-size: 2.5rem;"><strong>Job Outcomes After Graduation</strong></h2> <p>The aged care sector is one of Australia’s fastest-growing industries. With an ageing population, demand for qualified support workers continues to rise. Successful completion of this certificate III in individual support opens doors to job roles like:</p> <ul class="catpara"> <li>Aged Care Worker</li> <li>Home Care Assistant</li> <li>Residential Support Worker</li> <li>Personal Care Assistant</li> <li>Community Care Worker</li> </ul> <p>Whether you want full-time employment or flexible part-time roles, this qualification positions you well for a strong start in the healthcare and community services space.</p> <h2 style="font-size: 2.5rem;"><strong>Take the First Step Today</strong></h2> <p>Ready to join a growing industry where your work truly matters? The individual support course at Skyline International College is your gateway to a stable, meaningful career in aged care. Start a Career in Aged Care with Industry-Recognised Training near Sydney. <a data-wpel-link="internal" href="https://sic.edu.au/contact/">Contact us now</a> to learn more, check your eligibility, or begin your application. Your career in caring starts here.</p> </div> </section> </div>',
    total_course_duration = '52 Weeks(Includes term breaks)',
    offshore_tuition_fee = 14000,
    enrolment_fee = 200,
