UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>SIT40521 Certificate IV in Kitchen Management</strong></h1> <p>This qualification reflects the role of chefs and cooks who have a supervisory or team leading role in the kitchen. They operate independently or with limited guidance from others and use discretion to solve non-routine problems.</p> <p>This qualification provides a pathway to work in organisations such as restaurants, hotels, clubs, pubs, cafes and coffee shops, or to run a small business in these sectors</p> </div>',
