    enrolment_fee = 200,
    materials_fee = 400,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645853469895-f3f47771-9bc1" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) has set the entry requirements for this qualification.</p> <h4>Academic Requirements:</h4> <p><strong>No direct entry</strong></p> <p>There is NO Direct entry to the Diploma of Hospitality Management.</p> <h4>SIC Pathway Model</h4> <p>The entry requirement is evidence of completion of the SIT40521 Certificate IV in Kitchen Management</p> <h4>Credit Transfer will be individually managed</h4> <p>Skyline International College (SIC) will assess every individual application to SIT50422 and provide recognition through a Credit Transfer arrangement for the expected 19 units of competency</p> <h4>English Language Requirements:</h4> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/sit50422-diploma-of-hospitality-management/',
    updated_at = NOW()
WHERE cricos_course_code = '112275H';
UPDATE courses SET
    course_description = '<div class="wpb_wrapper"><h1><strong>SIT60322 Advanced Diploma of Hospitality Management</strong></h1> <p>The SIT60322 Advanced Diploma of Hospitality Management qualification reflects the role of highly skilled senior managers who use a broad range of hospitality skills combined with specialised managerial skills and substantial knowledge of industry to coordinate hospitality operations. They operate with significant autonomy and are responsible for making strategic business management decisions.</p> <p>This qualification provides a pathway to work in any hospitality industry sector and for a diversity of employers including restaurants, hotels, motels, catering operations, clubs, pubs, cafés, and coffee shops. This qualification allows for multi-skilling and for specialisation in accommodation services, cookery, food and beverage and gaming.</p> <h3><strong>Study And Enjoy Multicultural Burwood</strong></h3> <p>Skyline International College, Burwood campus is just 12 minutes by train from the heart of the city of Sydney. The campus is in the center of Burwood and is just 2 minutes of walk from the Burwood train station or bus stop. Burwood is multicultural and is a destination for international students to live and work.</p> </div>',
    total_course_duration = '2.5 Years(Includes term breaks)',
    offshore_tuition_fee = 22000,
    enrolment_fee = 200,
    materials_fee = 1200,
    entry_requirements = '<div aria-expanded="true" class="w-tabs-section-content" id="content-1645854272282-3e6eb764-973d" style=""><div class="w-tabs-section-content-h i-cf"><div class="wpb_text_column taab active"><div class="wpb_wrapper"><p>Skyline International College (SIC) follows the SIT Training package guidance for the entry requirements for this qualification. There are no entry requirements for this qualification and direct entry is accepted.</p> <h4>Academic Requirements:</h4> <p>Minimum completion of Australian Year 12 secondary school education equivalent or above. This requirement will vary by country of origin and information is provided on the SIC website and SIC marketing materials.</p> <h4>English Language Requirements:</h4> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Academic IELTS 6.0 overall, with no less than 5.5 in each band or Upper Intermediate or EAP completion from an approved ELICOS/ESL centre Or Equivalent English Test (e.g. PTE, TOEFL).</span></p> <p class="cvgsua" style="text-align: justify; color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --8sd0kg: none; --cyv3zq: 12px; --gjplxq: 1.985; --s8nbea: p;"><span style="color: rgba(35,31,32,var(--o42jjq,1)); caret-color: #231f20; --ys-xuq: none; font-kerning: none;"><span class="agcmg">An AQF qualification at Certificate III level or above in any discipline,</span> delivered and assessed in English, will also satisfy both academic and</span> English requirements.</p> <p class="cvgsua" style="text-align: justify;"><span class="agcmg">Successfully complete the Language, Literacy, and Numeracy (LLN) and Digital literacy assessment provided by SIC prior to finalization of enrolment.</span></p> </div></div></div></div>',
    apply_form = 'https://sic.edu.au/course/sit60322-advanced-diploma-of-hospitality-management/',
    updated_at = NOW()
WHERE cricos_course_code = '112276G';